export const WHATSAPP_NUMBER='963967765704';
export const UNLISTED_IDS=['MED-095','MED-112','MED-149','MED-150','MED-241'];
export function canOrder(p){return !!p&&!UNLISTED_IDS.includes(p.id)&&!p.review&&!p.issue&&Number.isFinite(p.price)&&p.price>0;}
export function normalizeCart(raw,products){const clean={};if(!raw||typeof raw!=='object'||Array.isArray(raw))return clean;for(const [id,value]of Object.entries(raw)){const p=products.find(p=>p.id===id);const qty=Number(value);if(canOrder(p)&&Number.isFinite(qty)&&qty>=1)clean[id]=Math.min(99,Math.floor(qty));}return clean;}
export function cartSummary(raw,products){const cart=normalizeCart(raw,products);const items=Object.entries(cart).map(([id,qty])=>({product:products.find(p=>p.id===id),qty}));return{items,count:items.reduce((s,i)=>s+i.qty,0),total:items.reduce((s,i)=>s+i.qty*i.product.price,0)};}
const amount=n=>new Intl.NumberFormat('en-US').format(n);
export function buildWhatsAppParts(raw,products,context={}){const summary=cartSummary(raw,products);if(!summary.items.length)return[];const p=context.pharmacy||{};const clip=(s,n)=>String(s||'').trim().slice(0,n);const name=clip(p.name,80);const heading=`مرحبًا مستودع العاصمة 🌿\nأرغب بطلب الأصناف التالية وتأكيد توفرها وأسعارها.${name?`\nالصيدلية: ${name}`:''}${context.invoiceId?`\nرقم الفاتورة: ${clip(context.invoiceId,60)}`:''}`;const footer=`إجمالي السلة الكاملة: ${amount(summary.total)} ل.س (${summary.count} قطعة / ${summary.items.length} صنف).\nالإجمالي تقديري ولا يشمل التوصيل. يرجى تأكيد الأسعار والتوفر وأي وصفة مطلوبة قبل التجهيز.`;const blocks=[];if(p.city)blocks.push('المدينة / المنطقة: '+clip(p.city,60));if(p.address)blocks.push('عنوان الصيدلية: '+clip(p.address,180));if(p.phone)blocks.push('هاتف الصيدلية: '+clip(p.phone,30));if(p.contact)blocks.push('المسؤول: '+clip(p.contact,80));if(p.notes)blocks.push('ملاحظات الطلب: '+clip(p.notes,240));for(const item of summary.items){const p=item.product;blocks.push(`• ${p.ar} [${p.id}]\nالكمية: ${item.qty} × ${amount(p.price)} ل.س = ${amount(item.qty*p.price)} ل.س`);}const budget=Math.max(1800,5500-encodeURIComponent(heading+footer).length-450);const groups=[];let group=[];for(const block of blocks){if(group.length&&encodeURIComponent([...group,block].join('\n\n')).length>budget){groups.push(group);group=[];}group.push(block);}if(group.length)groups.push(group);return groups.map((lines,i)=>{const text=`${heading}\n${groups.length>1?`قائمة الطلب — الجزء ${i+1} من ${groups.length}\n`:''}\n${lines.join('\n\n')}\n\n${footer}`;return{text,url:`https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent(text)}`};});}
